import {
  CircleGeometry, CylinderGeometry, Group, LatheGeometry, Mesh,
  MeshStandardMaterial, TorusGeometry, Vector2
} from 'three';

/** Create the neutral metal, shade and light materials used by the lamp. */
export function createLampMaterials() {
  return {
    metal: new MeshStandardMaterial({ color: 0x334155, roughness: 0.3, metalness: 0.75 }),
    shade: new MeshStandardMaterial({ color: 0xf2e7d5, roughness: 0.65, side: 2 }),
    glow: new MeshStandardMaterial({
      color: 0xffe8b6, emissive: 0xffc66a, emissiveIntensity: 0.5,
      roughness: 0.8, side: 2
    })
  };
}

/** Build the open shade shell from a radial profile, rotating around Y. */
export function createShadeGeometry() {
  const profile = [
    new Vector2(0.9, 0),
    new Vector2(0.9, 0.035),
    new Vector2(0.65, 0.615),
    new Vector2(0.63, 0.65)
  ];
  return new LatheGeometry(profile, 64);
}

/** Build the circular light panel in its local XY plane. */
export function createGlowPanelGeometry() {
  return new CircleGeometry(0.8, 64);
}

/** Build the lamp base without baking its placement into its vertices. */
export function createBaseGeometry() {
  return new CylinderGeometry(0.48, 0.55, 0.18, 48);
}

/** Build the narrow upright support for the shade. */
export function createStemGeometry() {
  return new CylinderGeometry(0.045, 0.055, 1.7, 24);
}

/** Create the compact decorative ring around the base of the stem. */
export function createCollarGeometry() {
  return new TorusGeometry(0.11, 0.025, 12, 32);
}

/** Assign stable object identity and a local position to a new mesh. */
function placedMesh(name, geometry, material, position) {
  const mesh = new Mesh(geometry, material);
  mesh.name = name;
  mesh.position.set(...position);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

/** Assemble the procedural desk lamp with separate editable components. */
export function createLampModel() {
  const materials = createLampMaterials();
  const lamp = new Group();
  lamp.name = 'Desk lamp';

  const base = placedMesh(
    'Base', createBaseGeometry(), materials.metal, [0, 0.09, 0]
  );
  const stem = placedMesh(
    'Stem', createStemGeometry(), materials.metal, [0, 1.03, 0]
  );
  const shade = placedMesh(
    'Lamp shade', createShadeGeometry(), materials.shade, [0, 1.9, 0]
  );
  const glow = placedMesh(
    'Glow panel', createGlowPanelGeometry(), materials.glow, [0, 1.895, 0]
  );
  glow.rotation.x = -Math.PI / 2;

  const collar = placedMesh(
    'Collar', createCollarGeometry(), materials.metal, [0, 0.23, 0]
  );
  collar.rotation.x = -Math.PI / 2;
  lamp.add(base, stem, shade, glow, collar);
  return lamp;
}

