const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const { pathToFileURL } = require('node:url');
const root = __dirname;
async function loadSource(sourcePath) {
  const threeURL = pathToFileURL(path.join(root, 'project/node_modules/three/build/three.module.js')).href;
  const source = fs.readFileSync(sourcePath, 'utf8').replace("from 'three'", `from '${threeURL}'`);
  return import(`data:text/javascript;base64,${Buffer.from(source).toString('base64')}`);
}
async function capture(sourcePath) {
  const { createLampModel } = await loadSource(sourcePath);
  const three = await import(pathToFileURL(path.join(root,'project/node_modules/three/build/three.module.js')).href);
  const lamp = createLampModel();
  lamp.updateMatrixWorld(true);
  const structure = [];
  const meshes = [];
  lamp.traverse(object => {
    structure.push({ name:object.name, type:object.type, parent:object.parent?.name??null, children:object.children.map(c=>c.name) });
    if (!object.isMesh) return;
    const position = object.geometry.getAttribute('position');
    const normal = object.geometry.getAttribute('normal');
    const uv = object.geometry.getAttribute('uv');
    const positions = [], normals = [];
    const normalMatrix = new three.Matrix3().getNormalMatrix(object.matrixWorld);
    for (let i=0;i<position.count;i++) {
      positions.push(...new three.Vector3().fromBufferAttribute(position,i).applyMatrix4(object.matrixWorld).toArray());
      normals.push(...new three.Vector3().fromBufferAttribute(normal,i).applyMatrix3(normalMatrix).normalize().toArray());
    }
    const material = object.material.toJSON();
    delete material.uuid; delete material.metadata;
    const box = new three.Box3().setFromObject(object);
    meshes.push({name:object.name,material,position:object.position.toArray(),quaternion:object.quaternion.toArray(),scale:object.scale.toArray(),castShadow:object.castShadow,receiveShadow:object.receiveShadow,
      attributes:Object.keys(object.geometry.attributes),positions,normals,uv:Array.from(uv.array),index:Array.from(object.geometry.index.array),bounds:{min:box.min.toArray(),max:box.max.toArray()}});
  });
  return {structure,rootTransform:lamp.matrixWorld.toArray(),meshes};
}
const close = (a,b,label) => assert(Math.abs(a-b)<3e-6, `${label}: ${a} != ${b}`);
(async()=>{
  const baselinePath = path.join(root,'baseline-geometry.json');
  if (process.argv[2] === 'baseline') {
    const baseline = await capture(path.join(root,'seed/lamp-model.js'));
    fs.writeFileSync(baselinePath,JSON.stringify(baseline));
    console.log(JSON.stringify({status:'BASELINE_READY',meshes:baseline.meshes.map(m=>({name:m.name,bounds:m.bounds}))}));
    return;
  }
  const baseline = JSON.parse(fs.readFileSync(baselinePath,'utf8'));
  const actual = await capture(path.join(root,'project/src/lamp-model.js'));
  assert.deepEqual(actual.structure,baseline.structure,'object identity/hierarchy');
  assert.deepEqual(actual.rootTransform,baseline.rootTransform,'root placement');
  let checkedNumbers=0;
  for(let i=0;i<actual.meshes.length;i++) {
    const next=actual.meshes[i], before=baseline.meshes[i];
    for(const key of ['name','material','position','quaternion','castShadow','receiveShadow','attributes','uv','index']) assert.deepEqual(next[key],before[key],`${next.name}/${key}`);
    const ratio=next.name==='Lamp shade'?2.6/1.8:next.name==='Glow panel'?2.4/1.6:1;
    assert.equal(next.positions.length,before.positions.length,'vertex count');
    assert.equal(next.normals.length,before.normals.length,'normal count');
    if(ratio===1) assert.deepEqual(next.scale,before.scale,`${next.name}/scale`);
    for(let j=0;j<next.positions.length;j+=3) {
      close(next.positions[j],before.positions[j]*ratio,`${next.name}/x`);
      close(next.positions[j+1],before.positions[j+1],`${next.name}/y`);
      close(next.positions[j+2],before.positions[j+2]*ratio,`${next.name}/z`);
      const expected=[before.normals[j]/ratio,before.normals[j+1],before.normals[j+2]/ratio];
      const length=Math.hypot(...expected);
      for(let k=0;k<3;k++) close(next.normals[j+k],expected[k]/length,`${next.name}/normal`);
      checkedNumbers+=6;
    }
    if(ratio!==1) {
      const diameter=next.name==='Lamp shade'?2.6:2.4;
      close(next.bounds.max[0]-next.bounds.min[0],diameter,`${next.name}/diameterX`);
      close(next.bounds.max[2]-next.bounds.min[2],diameter,`${next.name}/diameterZ`);
      close(next.bounds.min[1],before.bounds.min[1],`${next.name}/minY`);
      close(next.bounds.max[1],before.bounds.max[1],`${next.name}/maxY`);
    }
  }
  const receipt={status:'PASS',checkedNumbers,checks:['requested circular diameters','full position mapping including height','inverse-transpose normals','other components unchanged','materials/transforms/identity/hierarchy preserved','UV and index preservation'],meshes:actual.meshes.map(m=>({name:m.name,bounds:m.bounds}))};
  fs.writeFileSync(path.join(root,'geometry-verification.json'),JSON.stringify(receipt,null,2));
  console.log(JSON.stringify(receipt));
})().catch(error=>{console.error(error.stack);process.exitCode=1;});
